import math

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

# Iterate over x and even z such that 1 <= x, z < 100
valid_xz_case1 = []
for x in range(1, 100):
    for z in range(2, 100, 2): # z is even
        try:
            val = x**z + 1
            if is_power_of_two(val):
                valid_xz_case1.append((x, z, val))
        except OverflowError:
            # Skip if calculation results in overflow, although unlikely for base 100, exponent 100
            pass

print(f"Found {len(valid_xz_case1)} triples (x, z) where z is even and x^z+1 is a power of 2.")
# Print a few examples to understand the constraints
print("Sample triples (x, z, x^z+1):")
for x, z, val in valid_xz_case1[:10]:
    print(f"({x}, {z}, {val})")

def is_good_triple(x, y, z):
    numerator = (x + 1)**y
    denominator = x**z + 1
    if denominator == 0:
        return False # Should not happen for positive integers
    return numerator % denominator == 0

# Constraints for the targeted search
X_values = [2, 3, 4, 5]
Z_values = range(2, 100) # z in {2, 3, ..., 99}
Y_values = range(1, 100) # y in {1, 2, ..., 99}

good_triples = []

for x in X_values:
    for z in Z_values:
        for y in Y_values:
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

# Outputting the results in a readable format
print(f"Found {len(good_triples)} good triples.")
if good_triples:
    print("Triples found:")
    for triple in good_triples:
        print(triple)
else:
    print("No good triples found in the specified range.")

import math

def is_power_of_3(n):
    if n <= 0:
        return False
    if n == 1:
        return True
    while n % 3 == 0:
        n //= 3
    return n == 1

print("Checking $2^z + 1 = 3^m$ for $2 \le z < 100$.")
solutions = []

for z in range(2, 100):
    N = (2**z) + 1
    if is_power_of_3(N):
        # Find m such that N = 3^m
        m = round(math.log(N, 3))
        if 3**m == N:
            solutions.append((z, m))

if solutions:
    print("\nFound solutions (z, m):")
    for z, m in solutions:
        print(f"z = {z}, m = {m}")
else:
    print("\nNo solutions found in the range.")

# Determine the range of y for the found solutions
print("\nDetermining corresponding ranges of y:")
ranges_y = {}
for z, m in solutions:
    # We need y >= m and y < 100 (i.e., y <= 99)
    start_y = m
    end_y = 99

    if start_y <= end_y:
        count_y = end_y - start_y + 1
        ranges_y[z] = (start_y, end_y, count_y)
        print(f"For z={z} (where m={m}), y ranges from {start_y} to {end_y}. Count: {count_y}")

print("\nSummary of findings:")
print(ranges_y)
